// pt_report_core (Team D): the analyser on its own, loaded through vm exactly as tools/pt_report.cjs loads it (no page).
// Fixtures: tools/harness/fixtures/pt/ (generated by pt_lib.cjs from scripted runs; see its README).
//   node tools/harness/run.cjs tools/harness/scenarios/pt_report_core.cjs --html <build>/naceca.html
const fs = require('fs'), path = require('path'), vm = require('vm');
const P = require('./pt_lib.cjs');
module.exports = async h => {
  const SRC = path.join(P.ROOT, 'src', 'tactics', 'tac_pt_report.js');
  const box = {};
  vm.runInNewContext(fs.readFileSync(SRC, 'utf8'), box, { filename:SRC });
  const R = box.PT_REPORT;
  h.assert(R && typeof R.analyze === 'function' && !box.V12, 'the analyser loads in node through vm, with no page');
  const load = name => R.normalize(R.parse(P.fixture(name), name));
  const A = load('deviceA-desk.json'), Aearly = load('deviceA-desk-early.json'), B = load('deviceB-phone.txt'), C = load('deviceC-old.json');
  h.assert(A.length && B.length && C.length && Aearly.length, 'the fixtures parse');
  h.assert(!R.parse(P.fixture('broken.json'), 'broken.json').ok, 'broken.json is not a playtest log: ' + R.parse(P.fixture('broken.json')).reason);
  const all = R.dedupe(A.concat(Aearly, B, C));

  // dedupe: two exports of the same device count once; players are keyed by device + label
  h.assert(R.dedupe(A.concat(Aearly)).length === A.length && Aearly.every(e => A.some(x => x.sid === e.sid && x.t === e.t && x.type === e.type)), 'two exports of one device dedupe to the later one');
  const pl = R.players(all);
  h.log('players', pl.map(p => p.name + ':' + p.events.length).join(', '));
  const p1 = pl.find(p => p.label === 'P1'), p2 = pl.find(p => p.label === 'P2'), old = pl.find(p => !p.label);
  h.assert(pl.length === 3 && p1 && p2 && old, 'three players: P1, P2 and the v1 log');
  h.assert(/^[A-Z0-9]{4}·P1$/.test(p1.name) && /^[A-Z0-9]{4}·P2$/.test(p2.name), 'players print as dev·label: ' + p1.name + ', ' + p2.name);
  h.assert(R.matchPlayer(p1, p1.name) && R.matchPlayer(p1, 'p1') && R.matchPlayer(p1, p1.dev + '-P1') && !R.matchPlayer(p2, p1.name), '--player matches dev·label or the label');
  const r1 = R.analyze(p1.events), r2 = R.analyze(p2.events), r3 = R.analyze(old.events);
  [r1, r2, r3].forEach((r, i) => h.log(['P1', 'P2', 'v1'][i], JSON.stringify({ lost:r.lost.verdict, failed:r.failed.verdict, det:[r.detection.verdict, r.detection.flag], app:r.approaches.verdict, played:r.meta.playSecs, diff:r.meta.diff })));

  // P1: lost at the scan, wrong-target presses, LIKELY UNDERSTOOD, ≥ 2 chosen families
  const scan = r1.lost.rows.find(o => o.kind === 'obj' && o.obj === 'o2_scan');
  h.assert(scan && scan.level === 'lost' && scan.stuck >= 1, 'P1 got lost at the scan');
  const stolen = r1.failed.rows.find(r => r.kind === 'stolen');
  h.assert(stolen && stolen.n === 3 && stolen.label === 'Scan suspect phone' && /Confront/.test(stolen.want), 'P1: the scanned phone took the press three times (wrong target)');
  h.assert(r1.detection.flag === 'likely' && r1.detection.stamp === 'LIKELY UNDERSTOOD', 'P1: LIKELY UNDERSTOOD');
  h.assert(r1.approaches.families.length >= 2 && r1.approaches.families.includes('stealth'), 'P1 chose ≥ 2 families: ' + r1.approaches.families.join(', '));
  h.assert(r1.meta.diff === 'senior' && r1.meta.playSecs > 0 && r1.meta.kinds.join() === 'desk', 'P1: Senior Agent from new_game, played time, desktop');
  h.assert(r1.lost.screens.some(o => o.id === 'screen-ops' && o.open > 0) && !r1.lost.rows.some(o => o.kind === 'inv'), 'P1: the operations table is measured; a short visit with no strikes is not a row');

  // P2: ASK THEM, one family; a quit right after the survey isn't lost
  h.assert(r2.detection.flag === 'ask' && r2.detection.stamp === 'ASK THEM', 'P2: ASK THEM');
  h.assert(r2.detection.rows.length === 2 && r2.detection.rows.every(r => r.hasRead && !r.read) && r2.detection.unfair && r2.detection.unfair.aboutDetection, 'P2: two alarms on screen too briefly, and an unfair answer about being seen');
  h.assert(r2.approaches.families.length === 1 && r2.approaches.verdict === 'One: direct', 'P2: one family (' + r2.approaches.verdict + ')');
  const kc2 = r2.approaches.rows.find(r => r.enc === 'm2_kc');
  h.assert(kc2 && R.encLine(kc2) === 'M2 KC · chosen: direct (default); result: seen, then tackled', 'chosen and result are reported separately: ' + R.encLine(kc2));
  h.assert(p2.events.some(e => e.type === 'quit') && !r2.lost.rows.some(o => o.quit), 'P2 quit right after the two questions: not lost');
  const p2NoSurvey = p2.events.filter(e => e.type !== 'survey');
  h.assert(R.lost(p2NoSurvey).rows.some(o => o.quit && o.level === 'lost'), 'the same quit without the questions just before it is lost');
  h.assert(r2.failed.rows.some(r => r.kind === 'range' && r.n === 3), 'P2: three taps just out of reach (one coalesced event, rep 3)');
  h.assert(r2.meta.kinds.join() === 'touch', 'P2 played on a phone');

  // a v1 log: no detection data, no encounter data; its quit 140 s into an objective is lost
  h.assert(r3.detection.verdict === 'No detection data in this build' && r3.detection.flag === null, 'a v1 log → No detection data');
  h.assert(r3.approaches.verdict === 'No encounter data in this build', 'a v1 log → No encounter data');
  h.assert(r3.lost.rows.some(o => o.quit && o.level === 'lost'), 'the v1 log\'s quit counts as lost');

  // an alarm without seen_read → NO READ DATA (it wins over the other stamps)
  const noRead = R.detection(p1.events.filter(e => e.type !== 'seen_read'));
  h.assert(noRead.flag === 'none' && noRead.stamp === 'NO READ DATA', 'an alarm with no read record → NO READ DATA');

  // synthetic players
  let t = 1760000000000;
  const ev = (type, d, m, sid) => ({ t:(t += 1000), sid:sid || 's1', type, m:m || 'm2', d:Object.assign({ dev:'desk' }, d || {}) });
  const kcSeen = (o = {}) => ev('enc', Object.assign({ enc:'m2_kc', approach:'seen', intent:'direct', side:'front', how:'tackle', outcome:'caught' }, o));
  // an unposted Uche's callout is not a family; with a player order it is
  const callout = ev('ally_done', { who:'uche', task:'callout', outcome:'done', secs:2 });
  let ap = R.approaches([kcSeen(), callout]);
  h.assert(!ap.families.includes('Uche') && ap.verdict === 'None recognised', 'an unposted Uche\'s callout is not a family (' + ap.verdict + ')');
  ap = R.approaches([ev('order', { who:'uche', order:'post', post:'van', src:'talk', ok:true, def:false }), kcSeen(), callout]);
  h.assert(ap.families.includes('Uche'), 'an order the player gave + an act in the same mission → Uche');
  ap = R.approaches([ev('order', { who:'uche', order:'post', post:'corner', src:'talk', ok:true, def:false }, 'm2'), ev('ally_done', { who:'uche', task:'cover_held', outcome:'done', secs:1 }, 'm3')]);
  h.assert(!ap.families.includes('Uche') && ap.families.includes('preparation'), 'the order and the act must be in the same mission (a non-default post is still preparation)');
  // a defaults-only player
  ap = R.approaches([ev('enc', { enc:'m2_tunde', choice:'loud', tip:false, seen:true }), kcSeen(), ev('m2_summary', { crouchNearSecs:0 }),
    ev('enc', { enc:'m3_entry', entry:'knock', door:'front', power:'on', def:{ entry:true, power:true } }, 'm3'), ev('enc', { enc:'m3_obi', outcome:'perimeter', by:'perimeter' }, 'm3')]);
  h.assert(ap.verdict === 'None recognised', 'a defaults-only player → None recognised (' + ap.verdict + ')');
  // stealth intent: crouched near him, or pressed from the side, even when he saw them
  h.assert(R.approaches([kcSeen(), ev('m2_summary', { crouchNearSecs:3 })]).families.join() === 'stealth', 'crouchNearSecs ≥ 2 is stealth intent');
  h.assert(R.approaches([kcSeen({ side:'behind' })]).families.join() === 'stealth', 'a press from behind is stealth intent');
  h.assert(R.approaches([kcSeen({ how:'cutoff' })]).families.join() === 'intercept', 'a cut-off is intercept');
  h.assert(R.approaches([ev('enc', { enc:'m3_entry', entry:'quiet', door:'gate', power:'cut', def:{ entry:false, power:false } }, 'm3')]).families.sort().join() === 'preparation,stealth', 'M3 quiet → stealth; gate and power cut → preparation');
  h.assert(R.approaches([ev('enc', { enc:'m3_entry', entry:'knock', door:'front', power:'cut', def:{ entry:true, power:true } }, 'm3')]).verdict === 'None recognised', 'knock and power left at their defaults → none');

  // detection rules
  h.assert(R.readMs(3) === 1500 && R.readMs(8) === 1920, 'READ_MS = max(1500, words × 240)');
  h.assert(!R.DETECT_WORDS.test('It made me angry') && !R.DETECT_WORDS.test('the eye thing was cute') && R.DETECT_WORDS.test('he saw me through a wall') && R.DETECT_WORDS.test('I was hiding'), 'DETECT_WORDS without "made me" and "eye"');
  const al = (why, o) => ev('seen', Object.assign({ who:'kc', enc:'m2_kc', level:'alarm', cause:'sight', why, crouch:false, gait:'walk' }, o || {}));
  const rd = (ms, words) => ev('seen_read', { who:'kc', enc:'m2_kc', ms, via:'eye', words, end:'hidden' });
  let det = R.detection([al('He saw you crossing the open road, standing'), rd(2100, 8), al('He saw you crossing the open road, standing'), rd(2000, 8)]);
  h.assert(det.flag === 'likely' && det.repeats.length === 1 && det.rows.filter(r => r.repeat).length === 1, '"same reason again" is an evidence row, not a stamp input');
  det = R.detection([al('He saw you crossing the open road, standing'), rd(1800, 8)]);
  h.assert(det.flag === 'ask', '1.8 s for an 8-word line (needs 1.92 s) → ASK THEM');
  det = R.detection([al('x', { cause:'tunde_glance' }), ev('seen', { who:'kc', enc:'m2_kc', level:'notice', cause:'sight' })]);
  h.assert(det.flag === null && det.alarms === 0 && /never seen/.test(det.verdict), 'only sight|noise|close|scan|fumble|tunde alarms are judged: ' + det.verdict);
  // pairing by alarm order, per watcher
  det = R.detection([al('A one two'), al('B one two', { who:'obi', enc:'m3_obi' }), ev('seen_read', { who:'obi', enc:'m3_obi', ms:300, via:'toast', words:3, end:'hidden' }), rd(1600, 3)]);
  h.assert(det.rows[0].readMs === 1600 && det.rows[1].readMs === 300, 'seen_read pairs with its own alarm (by order, per watcher)');
  det = R.detection([al('A'), ev('seen_read', { who:'kc', enc:'m2_kc', ms:0, via:null, words:1, end:'timeout' })]);
  h.assert(det.flag === 'ask' && /never on screen/.test(R.seenLine(det.rows[0])), 'a line that never reached the screen reads "reason never on screen"');

  // failed: noop is not a failure; blocked is refused without a press
  const f = R.failed([ev('interact_result', { label:'Talk', outcome:'noop' }), ev('interact_result', { label:'Gate', outcome:'refused', toast:{ big:'NOT YET' } }), ev('blocked', { big:'BACK TO THE TABLE', small:'x', rep:2 })]);
  h.assert(f.presses === 2 && f.fails === 1 && f.rows.some(r => r.kind === 'blocked' && r.n === 2), 'noop is not a failure; blocked counts its reps, without a press');

  // investigation rows
  const inv = R.lost([ev('ops_open', { m:'h2' }, 'h2'), ev('strike', { k:'a', c:'lagos', n:1 }, 'h2'), ev('strike', { k:'b', c:'lagos', n:2 }, 'h2'), ev('strike', { k:'c', c:'lagos', n:3 }, 'h2'),
    ev('file', { n:3, ok:0, struck:3 }, 'h2'), ev('ov_dwell', { id:'screen-ops', secs:400, obj:'o1' }, 'h2'), ev('doc_failed', { key:'market_phone_scan' }), ev('warrant', { c:'lagos', w:'refused', strikes:3 }, 'h2'),
    ev('v13_verdict', { st:'s', c:'c', v:'contradicted' }, 'h2'), ev('ov_dwell', { id:'screen-desk', secs:250, obj:'o1' }, 'h2'), ev('ov_dwell', { id:'screen-pause', secs:999 }, 'h2')]);
  const ops = inv.rows.find(o => o.id === 'screen-ops');
  h.log('investigation rows', JSON.stringify(inv.rows.map(R.lostLine)));
  h.assert(ops && R.lostLine(ops) === 'H2 · operations table: 6:40 open, 3 strikes, 3 links struck, lost' && ops.level === 'lost', 'the operations table row: "operations table: 6:40 open, 3 strikes"');
  h.assert(inv.rows.some(o => o.id === 'warrant' && o.refused === 1) && inv.rows.some(o => o.id === 'screen-puzzle' && o.docFailed === 1) && inv.rows.some(o => o.id === 'screen-desk' && o.verdicts === 1 && o.open === 250), 'warrant, document and desk rows');
  h.assert(!inv.rows.some(o => o.id === 'screen-pause'), 'menus are not investigation');

  // meta: difficulty from new_game, played time per session from ps, independent per player
  const meta = R.meta([ev('session', { settings:{ casework:'recruit' }, ps:0, p:'P2' }), ev('new_game', { d:'senior', ps:3, p:'P2' }), ev('x', { ps:100, p:'P2' }), ev('session', { ps:0, p:'P2' }, 'm2', 's2'), ev('x', { ps:40, p:'P2' }, 'm2', 's2')]);
  h.assert(meta.diff === 'senior' && meta.playSecs === 140, 'difficulty from new_game.d; played = per session first to last ps (' + meta.diff + ', ' + meta.playSecs + ')');

  // the text renderer prints the same rows the sheet shows (shared functions)
  const L = R.text(r1, p1.name).join('\n'), S = R.sections(r1);
  h.assert(R.Q.every(q => L.includes(q.toUpperCase())) && S.every(s => s.rows.slice(0, 5).every(row => L.includes('  - ' + row))), 'R.text prints the sections\' rows');
  h.assert(S.map(s => s.q).join('|') === 'Where did they get lost?|Which interactions failed?|Did they understand why they were seen?|Did they use more than one approach?', 'the four questions word for word');
  const X = R.across([{ name:p1.name, res:r1 }, { name:p2.name, res:r2 }, { name:old.name, res:r3 }]);
  const XT = R.acrossText(X).join('\n');
  h.assert(/^ACROSS 3 PLAYERS/.test(XT) && X.famN['2+'] === 1 && X.famN[1] === 1 && X.famN[0] === 1, 'across players: 2+ / one / none');
  const md = R.markdown([{ name:p1.name, res:r1 }], null);
  h.assert(/^# NACECA playtest report/.test(md) && md.includes('### Did they understand why they were seen?') && md.includes('`LIKELY UNDERSTOOD`'), 'the Markdown report');
  const txt = JSON.stringify([L, XT, md]);
  h.assert(!/\bAKS\b/.test(txt) && !/[\u{1F300}-\u{1FAFF}\u{2600}-\u{27BF}\u{2190}-\u{21FF}]/u.test(txt), 'no AKS, no emoji or arrow glyphs in the report text');
  h.assert(h.errors.length === 0, 'no page errors');
};
